import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { AuthProvider } from './contexts/AuthContext';
import ProtectedRoute from './components/ProtectedRoute';
import LandingPage from './pages/LandingPage';
import LoginPage from './pages/LoginPage';
import SignupPage from './pages/SignupPage';
import ChatPage from './pages/ChatPage';

function App() {
  return (
    <AuthProvider>
      <Router>
        <div className="App">
          <Routes>
            {/* Public Routes */}
            <Route path="/" element={<LandingPage />} />
            <Route path="/login" element={<LoginPage />} />
            <Route path="/signup" element={<SignupPage />} />
            
            {/* Protected Routes */}
            <Route 
              path="/chat" 
              element={
                <ProtectedRoute>
                  <ChatPage />
                </ProtectedRoute>
              } 
            />
            
            {/* Redirect any unknown routes to home */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
          
          {/* Toast Notifications */}
          <Toaster
            position="top-right"
            toastOptions={{
              duration: 3000,
              style: {
                background: '#fff',
                color: '#8b6914',
                border: '1px solid #f4e4d1',
                borderRadius: '12px',
                padding: '12px 16px',
                fontSize: '14px',
                fontWeight: '500',
              },
              success: {
                iconTheme: {
                  primary: '#d4a574',
                  secondary: '#fff',
                },
              },
              error: {
                iconTheme: {
                  primary: '#ef4444',
                  secondary: '#fff',
                },
              },
            }}
          />
        </div>
      </Router>
    </AuthProvider>
  );
}

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Send, Mic, MicOff, Image, X, Paperclip, FileText, Loader2 } from 'lucide-react';
import speechService from '../services/speechService';
import { chatAPI } from '../services/api';
import toast from 'react-hot-toast';

const ChatInput = ({ onSendMessage, disabled, statusMessage }) => {
  const [message, setMessage] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [selectedImage, setSelectedImage] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const [isUploading, setIsUploading] = useState(false);
  const [showAttachMenu, setShowAttachMenu] = useState(false);
  
  const imageInputRef = useRef(null);
  const docInputRef = useRef(null);
  const textareaRef = useRef(null);
  const attachMenuRef = useRef(null);

  // Close attach menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (attachMenuRef.current && !attachMenuRef.current.contains(event.target)) {
        setShowAttachMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (message.trim() || selectedImage) {
      onSendMessage(message.trim(), selectedImage);
      setMessage('');
      setSelectedImage(null);
      setImagePreview(null);
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
      }
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e);
    }
  };

  const handleTextareaChange = (e) => {
    setMessage(e.target.value);
    
    // Auto-resize textarea
    const textarea = e.target;
    textarea.style.height = 'auto';
    textarea.style.height = Math.min(textarea.scrollHeight, 120) + 'px';
  };

  const handleVoiceInput = () => {
    if (!speechService.isSupported()) {
      toast.error('Speech recognition is not supported in your browser.');
      return;
    }

    if (isListening) {
      speechService.stopListening();
      setIsListening(false);
    } else {
      setIsListening(true);
      speechService.startListening(
        (transcript) => {
          setMessage(prev => prev + (prev ? ' ' : '') + transcript);
          setIsListening(false);
          toast.success('Voice input captured!');
        },
        (error) => {
          console.error('Speech recognition error:', error);
          setIsListening(false);
          toast.error('Voice input failed. Please try again.');
        }
      );
    }
  };

  const handleImageSelect = (e) => {
    const file = e.target.files[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) { // 5MB limit
        toast.error('Image size should be less than 5MB');
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        const base64 = e.target.result;
        setSelectedImage(base64);
        setImagePreview(base64);
        setShowAttachMenu(false);
        toast.success('Image selected!');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDocSelect = async (e) => {
    const file = e.target.files[0];
    if (file) {
      setIsUploading(true);
      setShowAttachMenu(false);
      try {
        await chatAPI.uploadDocument(file);
        toast.success(`Document "${file.name}" indexed for RAG!`);
      } catch (error) {
        toast.error(error.message || 'Failed to index document.');
      } finally {
        setIsUploading(false);
        if (docInputRef.current) docInputRef.current.value = '';
      }
    }
  };

  const removeImage = () => {
    setSelectedImage(null);
    setImagePreview(null);
    if (imageInputRef.current) {
      imageInputRef.current.value = '';
    }
  };

  return (
    <div className="bg-navy-800 border-t border-navy-700 p-4">
      {/* Image Preview */}
      <AnimatePresence>
        {imagePreview && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="mb-4"
          >
            <div className="relative inline-block">
              <img 
                src={imagePreview} 
                alt="Selected" 
                className="max-w-32 max-h-32 rounded-xl border border-navy-700 shadow-md"
              />
              <motion.button
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={removeImage}
                className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1.5 hover:bg-red-600 shadow-lg"
              >
                <X className="w-3 h-3" />
              </motion.button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      
      {/* Input Form */}
      <form onSubmit={handleSubmit} className="flex items-end space-x-3">
        <input
          type="file"
          ref={imageInputRef}
          onChange={handleImageSelect}
          accept="image/*"
          className="hidden"
        />
        <input
          type="file"
          ref={docInputRef}
          onChange={handleDocSelect}
          accept=".pdf,.txt,.md,.doc,.docx,.json,.csv"
          className="hidden"
        />
        
        {/* Attachment Button & Menu */}
        <div className="relative" ref={attachMenuRef}>
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            type="button"
            onClick={() => setShowAttachMenu(!showAttachMenu)}
            className={`p-3 rounded-xl transition-all duration-200 ${
              showAttachMenu ? 'bg-sand-100 text-sand-700' : 'text-warm-500 hover:text-warm-700 hover:bg-navy-800'
            }`}
            title="Attach file"
            disabled={disabled || isUploading}
          >
            {isUploading ? (
              <Loader2 className="w-5 h-5 animate-spin text-sand-600" />
            ) : (
              <Paperclip className="w-5 h-5" />
            )}
          </motion.button>

          <AnimatePresence>
            {showAttachMenu && (
              <motion.div
                initial={{ opacity: 0, scale: 0.9, y: -10 }}
                animate={{ opacity: 1, scale: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.9, y: -10 }}
                className="absolute bottom-full mb-2 left-0 bg-navy-800 rounded-xl shadow-2xl border border-navy-700 p-2 min-w-[160px] z-50"
              >
                <button
                  type="button"
                  onClick={() => imageInputRef.current?.click()}
                  className="w-full flex items-center space-x-3 px-3 py-2 hover:bg-navy-700 rounded-lg transition-colors text-warm-700"
                >
                  <Image className="w-4 h-4 text-blue-500" />
                  <span className="text-sm font-medium">Image</span>
                </button>
                <button
                  type="button"
                  onClick={() => docInputRef.current?.click()}
                  className="w-full flex items-center space-x-3 px-3 py-2 hover:bg-navy-700 rounded-lg transition-colors text-warm-700"
                >
                  <FileText className="w-4 h-4 text-green-500" />
                  <span className="text-sm font-medium">Document</span>
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Text Input */}
        <div className="flex-1 relative">
          <textarea
            ref={textareaRef}
            value={message}
            onChange={handleTextareaChange}
            onKeyPress={handleKeyPress}
            placeholder="Type your message... (Press Enter to send)"
            className="w-full px-4 py-3 pr-12 bg-navy-700 border border-beige-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-sand-500 focus:border-transparent transition-all duration-200 resize-none min-h-[48px] max-h-[120px]"
            disabled={disabled || isUploading}
            rows={1}
          />
          
          {/* Voice Input Button */}
          {speechService.isSupported() && (
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              type="button"
              onClick={handleVoiceInput}
              className={`absolute right-3 top-1/2 transform -translate-y-1/2 p-2 rounded-lg transition-all duration-200 ${
                isListening 
                  ? 'bg-red-500 text-white hover:bg-red-600 animate-pulse' 
                  : 'text-warm-500 hover:text-warm-700 hover:bg-navy-800'
              }`}
              title={isListening ? 'Stop listening' : 'Voice input'}
              disabled={disabled || isUploading}
            >
              {isListening ? <MicOff className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
            </motion.button>
          )}
        </div>

        {/* Send Button */}
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          type="submit"
          disabled={disabled || isUploading || (!message.trim() && !selectedImage)}
          className="p-3 bg-sand-600 text-white rounded-xl hover:bg-sand-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-200 shadow-lg hover:shadow-xl disabled:hover:scale-100"
        >
          <Send className="w-5 h-5" />
        </motion.button>
      </form>

      {statusMessage && (
        <p className="mt-3 text-xs text-warm-500">
          {statusMessage}
        </p>
      )}

      {/* Voice Listening Indicator */}
      <AnimatePresence>
        {isListening && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="mt-3 flex items-center justify-center space-x-2 text-red-600"
          >
            <motion.div
              animate={{ scale: [1, 1.2, 1] }}
              transition={{ duration: 1, repeat: Infinity }}
              className="w-2 h-2 bg-red-500 rounded-full"
            />
            <span className="text-sm font-medium">Listening...</span>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default ChatInput;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { User, Bot, Volume2, Copy, Check } from 'lucide-react';
import speechService from '../services/speechService';
import toast from 'react-hot-toast';

import ReactMarkdown from 'react-markdown';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism';
import remarkGfm from 'remark-gfm';

const ChatMessage = ({ message, isUser, timestamp, imageUrl, index }) => {
  const [copied, setCopied] = useState(false);

  const handleSpeak = () => {
    if (!isUser && message) {
      speechService.speak(message);
    }
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(message);
      setCopied(true);
      toast.success('Message copied!');
      setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      toast.error('Failed to copy message');
    }
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleTimeString([], { 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3, delay: index * 0.1 }}
      className={`flex items-start space-x-3 mb-6 ${isUser ? 'flex-row-reverse space-x-reverse' : ''}`}
    >
      {/* Avatar */}
      <motion.div
        initial={{ scale: 0 }}
        animate={{ scale: 1 }}
        transition={{ duration: 0.3, delay: index * 0.1 + 0.1 }}
        className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center shadow-lg ${
          isUser 
            ? 'bg-gradient-to-br from-sand-500 to-sand-700' 
            : 'bg-gradient-to-br from-warm-400 to-warm-600'
        }`}
      >
        {isUser ? (
          <User className="w-5 h-5 text-white" />
        ) : (
          <Bot className="w-5 h-5 text-white" />
        )}
      </motion.div>
      
      <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} max-w-full lg:max-w-3xl`}>
        {/* Image if present */}
        {imageUrl && (
          <motion.img 
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            src={imageUrl} 
            alt="Uploaded content" 
            className="max-w-full h-auto rounded-xl mb-3 border border-navy-700 shadow-md"
          />
        )}
        
        {/* Message Bubble */}
        <motion.div
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          className={`message-bubble relative group w-full ${isUser ? 'user-message' : 'ai-message'}`}
        >
          <div className="prose prose-sm max-w-none dark:prose-invert">
            <ReactMarkdown
              remarkPlugins={[remarkGfm]}
              components={{
                code({ node, inline, className, children, ...props }) {
                  const match = /language-(\w+)/.exec(className || '');
                  return !inline && match ? (
                    <SyntaxHighlighter
                      style={vscDarkPlus}
                      language={match[1]}
                      PreTag="div"
                      {...props}
                    >
                      {String(children).replace(/\n$/, '')}
                    </SyntaxHighlighter>
                  ) : (
                    <code className={className} {...props}>
                      {children}
                    </code>
                  );
                }
              }}
            >
              {message}
            </ReactMarkdown>
          </div>
          
          {/* Action Buttons */}
          <div className={`absolute top-2 opacity-0 group-hover:opacity-100 transition-opacity duration-200 flex space-x-1 ${
            isUser ? '-left-16' : '-right-16'
          }`}>
            {!isUser && speechService.isSupported() && (
              <motion.button
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={handleSpeak}
                className="p-2 bg-navy-800 rounded-lg shadow-md hover:bg-navy-700 transition-colors border border-navy-700"
                title="Read aloud"
              >
                <Volume2 className="w-4 h-4 text-warm-600" />
              </motion.button>
            )}
            
            <motion.button
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={handleCopy}
              className="p-2 bg-navy-800 rounded-lg shadow-md hover:bg-navy-700 transition-colors border border-navy-700"
              title="Copy message"
            >
              {copied ? (
                <Check className="w-4 h-4 text-green-600" />
              ) : (
                <Copy className="w-4 h-4 text-warm-600" />
              )}
            </motion.button>
          </div>
        </motion.div>
        
        {/* Timestamp */}
        {timestamp && (
          <motion.span
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.3, delay: index * 0.1 + 0.3 }}
            className="text-xs text-warm-400 mt-2 px-1"
          >
            {formatTime(timestamp)}
          </motion.span>
        )}
      </div>
    </motion.div>
  );
};

export default ChatMessage;

import React from 'react';
import { motion } from 'framer-motion';

const LoadingSpinner = ({ size = 'md', text = 'Loading...' }) => {
  const sizeClasses = {
    sm: 'w-4 h-4',
    md: 'w-8 h-8',
    lg: 'w-12 h-12'
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-navy-700">
      <motion.div
        className={`${sizeClasses[size]} border-4 border-navy-700 border-t-sand-600 rounded-full`}
        animate={{ rotate: 360 }}
        transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
      />
      {text && (
        <motion.p 
          className="mt-4 text-warm-600 font-medium"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.2 }}
        >
          {text}
        </motion.p>
      )}
    </div>
  );
};

export default LoadingSpinner;

import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import LoadingSpinner from './LoadingSpinner';

const ProtectedRoute = ({ children }) => {
  const { isAuthenticated, loading } = useAuth();
  const location = useLocation();

  if (loading) {
    return <LoadingSpinner />;
  }

  if (!isAuthenticated) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  return children;
};

export default ProtectedRoute;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Bot, Plus, MessageCircle, Settings, LogOut, User, Menu, X } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';

const Sidebar = ({ onNewChat, chatHistory = [], currentChatId, onSelectChat }) => {
  const { user, logout } = useAuth();
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  const handleLogout = () => {
    logout();
    toast.success('Logged out successfully');
  };

  const handleNewChat = () => {
    onNewChat();
    toast.success('New chat started');
  };

  return (
    <>
      {/* Mobile Toggle Button */}
      <button
        onClick={() => setIsCollapsed(!isCollapsed)}
        className="lg:hidden fixed top-4 left-4 z-50 p-2 bg-navy-800 rounded-lg shadow-lg border border-navy-700"
      >
        {isCollapsed ? <Menu className="w-5 h-5" /> : <X className="w-5 h-5" />}
      </button>

      {/* Sidebar */}
      <motion.div
        initial={false}
        animate={{
          width: isCollapsed ? 0 : 280,
          opacity: isCollapsed ? 0 : 1
        }}
        transition={{ duration: 0.3 }}
        className={`fixed lg:relative inset-y-0 left-0 z-40 sidebar overflow-hidden ${
          isCollapsed ? 'lg:w-0' : 'lg:w-80'
        }`}
      >
        <div className="flex flex-col h-full p-4">
          {/* Header */}
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 bg-gradient-to-br from-sand-500 to-sand-700 rounded-xl flex items-center justify-center shadow-lg">
                <Bot className="w-6 h-6 text-white" />
              </div>
              <div>
                <h1 className="text-lg font-bold text-warm-900">AI.BH</h1>
                <p className="text-xs text-warm-600">Assistant</p>
              </div>
            </div>
          </div>

          {/* New Chat Button */}
          <motion.button
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            onClick={handleNewChat}
            className="w-full flex items-center justify-center space-x-2 bg-sand-600 hover:bg-sand-700 text-white font-medium py-3 px-4 rounded-xl transition-all duration-200 shadow-lg hover:shadow-xl mb-6"
          >
            <Plus className="w-5 h-5" />
            <span>New Chat</span>
          </motion.button>

          {/* Chat History */}
          <div className="flex-1 overflow-y-auto">
            <h3 className="text-sm font-medium text-warm-700 mb-3 px-2">Recent Chats</h3>
            <div className="space-y-2">
              {chatHistory.length > 0 ? (
                chatHistory.map((chat, index) => (
                  <motion.button
                    key={chat.id || index}
                    whileHover={{ x: 4 }}
                    onClick={() => onSelectChat(chat.id)}
                    className={`w-full flex items-center space-x-3 p-3 rounded-xl transition-all duration-200 text-left ${
                      currentChatId === chat.id
                        ? 'bg-sand-100 border border-sand-200'
                        : 'hover:bg-navy-800'
                    }`}
                  >
                    <MessageCircle className="w-4 h-4 text-warm-500 flex-shrink-0" />
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-warm-800 truncate">
                        {chat.title || `Chat ${index + 1}`}
                      </p>
                      <p className="text-xs text-warm-500 truncate">
                        {chat.lastMessage || 'No messages yet'}
                      </p>
                    </div>
                  </motion.button>
                ))
              ) : (
                <div className="text-center py-8">
                  <MessageCircle className="w-8 h-8 text-warm-300 mx-auto mb-2" />
                  <p className="text-sm text-warm-500">No chats yet</p>
                  <p className="text-xs text-warm-400">Start a conversation!</p>
                </div>
              )}
            </div>
          </div>

          {/* User Profile Section */}
          <div className="border-t border-beige-300 pt-4 mt-4">
            <div className="relative">
              <motion.button
                whileHover={{ scale: 1.02 }}
                onClick={() => setShowProfile(!showProfile)}
                className="w-full flex items-center space-x-3 p-3 rounded-xl hover:bg-navy-800 transition-all duration-200"
              >
                <div className="w-8 h-8 bg-gradient-to-br from-warm-400 to-warm-600 rounded-full flex items-center justify-center">
                  <User className="w-4 h-4 text-white" />
                </div>
                <div className="flex-1 text-left">
                  <p className="text-sm font-medium text-warm-800">{user?.name || 'User'}</p>
                  <p className="text-xs text-warm-500">{user?.email}</p>
                </div>
              </motion.button>

              {/* Profile Dropdown */}
              <AnimatePresence>
                {showProfile && (
                  <motion.div
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    className="absolute bottom-full left-0 right-0 mb-2 bg-navy-800 rounded-xl shadow-xl border border-navy-700 overflow-hidden"
                  >
                    <button className="w-full flex items-center space-x-3 p-3 hover:bg-navy-700 transition-colors text-left">
                      <Settings className="w-4 h-4 text-warm-500" />
                      <span className="text-sm text-warm-700">Settings</span>
                    </button>
                    <button
                      onClick={handleLogout}
                      className="w-full flex items-center space-x-3 p-3 hover:bg-red-50 transition-colors text-left border-t border-beige-100"
                    >
                      <LogOut className="w-4 h-4 text-red-500" />
                      <span className="text-sm text-red-600">Logout</span>
                    </button>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </div>
        </div>
      </motion.div>

      {/* Overlay for mobile */}
      {!isCollapsed && (
        <div
          className="lg:hidden fixed inset-0 bg-black bg-opacity-50 z-30"
          onClick={() => setIsCollapsed(true)}
        />
      )}
    </>
  );
};

export default Sidebar;

import React from 'react';
