import React, { createContext, useContext, useState, useEffect } from 'react';
import { authAPI } from '../services/authAPI';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

// Helper function to extract error messages
export const extractErrorMessage = (error) => {
  // API error response
  if (error.response?.data?.message) {
    return error.response.data.message;
  }
  
  // Network error
  if (error.message === 'Network Error') {
    return 'Unable to connect to server. Please try again.';
  }
  
  // Timeout error
  if (error.code === 'ECONNABORTED') {
    return 'Request timed out. Please try again.';
  }
  
  // Generic error
  return error.message || 'An unexpected error occurred';
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [token, setToken] = useState(localStorage.getItem('token'));

  useEffect(() => {
    const initAuth = async () => {
      const savedToken = localStorage.getItem('token');
      const savedUser = localStorage.getItem('user');
      
      if (savedToken && savedUser) {
        setToken(savedToken);
        setUser(JSON.parse(savedUser));
      }
      setLoading(false);
    };

    initAuth();
  }, []);

  const login = async (email, password) => {
    try {
      const response = await authAPI.login(email, password);
      const { token: newToken, refreshToken, user: userData } = response;
      
      localStorage.setItem('token', newToken);
      localStorage.setItem('refreshToken', refreshToken);
      localStorage.setItem('user', JSON.stringify(userData));
      
      setToken(newToken);
      setUser(userData);
      
      return { success: true };
    } catch (error) {
      return { 
        success: false, 
        error: extractErrorMessage(error)
      };
    }
  };

  const signup = async (firstName, lastName, email, password) => {
    try {
      const response = await authAPI.signup(firstName, lastName, email, password);
      const { token: newToken, refreshToken, user: userData } = response;
      
      localStorage.setItem('token', newToken);
      localStorage.setItem('refreshToken', refreshToken);
      localStorage.setItem('user', JSON.stringify(userData));
      
      setToken(newToken);
      setUser(userData);
      
      return { success: true };
    } catch (error) {
      return { 
        success: false, 
        error: extractErrorMessage(error)
      };
    }
  };

  const logout = async () => {
    try {
      await authAPI.logout();
    } catch (error) {
      console.warn('Logout API call failed:', error);
    } finally {
      localStorage.removeItem('token');
      localStorage.removeItem('refreshToken');
      localStorage.removeItem('user');
      setToken(null);
      setUser(null);
    }
  };

  const value = {
    user,
    token,
    login,
    signup,
    logout,
    isAuthenticated: !!token,
    loading
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Bot, AlertTriangle, CheckCircle2 } from 'lucide-react';
import Sidebar from '../components/Sidebar';
import ChatMessage from '../components/ChatMessage';
import ChatInput from '../components/ChatInput';
import TypingIndicator from '../components/TypingIndicator';
import { chatAPI } from '../services/api';
import speechService from '../services/speechService';
import toast from 'react-hot-toast';

const ChatPage = () => {
  const [messages, setMessages] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [sessionId, setSessionId] = useState(null);
  const [chatHistory, setChatHistory] = useState([]);
  const [currentChatId, setCurrentChatId] = useState(null);
  const [serviceHealth, setServiceHealth] = useState(null);
  const [healthMessage, setHealthMessage] = useState('Checking AI service status...');
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    bootstrapChat();
    checkHealth();
    const intervalId = setInterval(checkHealth, 30000);
    return () => clearInterval(intervalId);
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const bootstrapChat = async () => {
    try {
      const conversations = await chatAPI.getConversations();
      const mappedConversations = mapConversationSummaries(conversations);
      setChatHistory(mappedConversations);

      if (mappedConversations.length > 0) {
        await loadConversation(mappedConversations[0].id);
        return;
      }
    } catch (error) {
      console.error('Failed to bootstrap conversations:', error);
    }

    initializeChat();
  };

  const initializeChat = () => {
    const newSessionId = generateSessionId();
    setSessionId(newSessionId);
    setCurrentChatId(newSessionId);
    
    // Add welcome message
    const welcomeMessage = {
      id: 1,
      message: "Welcome to AI.BH. I am your professional assistant. How can I help you today?",
      isUser: false,
      timestamp: new Date().toISOString()
    };
    
    setMessages([welcomeMessage]);
    
    // Speak welcome message if speech is supported
    setTimeout(() => {
      if (speechService.isSupported()) {
        speechService.speak(welcomeMessage.message);
      }
    }, 1000);
  };

  const mapConversationSummaries = (conversations) => (
    conversations.map((chat) => ({
      id: chat.sessionId,
      title: chat.title,
      lastMessage: chat.lastMessage,
      createdAt: chat.createdAt,
      updatedAt: chat.updatedAt
    }))
  );

  const hydrateMessages = (history) => {
    const hydrated = [];

    history.forEach((entry) => {
      if (entry.userMessage) {
        hydrated.push({
          id: `${entry.id}-user`,
          message: entry.userMessage,
          isUser: true,
          timestamp: entry.createdAt,
          imageUrl: entry.imageUrl || null
        });
      }

      if (entry.aiResponse) {
        hydrated.push({
          id: `${entry.id}-ai`,
          message: entry.aiResponse,
          isUser: false,
          timestamp: entry.createdAt
        });
      }
    });

    return hydrated;
  };

  const refreshConversations = async () => {
    try {
      const conversations = await chatAPI.getConversations();
      setChatHistory(mapConversationSummaries(conversations));
    } catch (error) {
      console.error('Failed to refresh conversations:', error);
    }
  };

  const loadConversation = async (chatId) => {
    setIsLoadingHistory(true);
    try {
      const history = await chatAPI.getChatHistory(chatId);
      setCurrentChatId(chatId);
      setSessionId(chatId);
      setMessages(hydrateMessages(history));
    } catch (error) {
      console.error('Failed to load conversation:', error);
      toast.error('Failed to load conversation history.');
    } finally {
      setIsLoadingHistory(false);
    }
  };

  const checkHealth = async () => {
    try {
      const health = await chatAPI.healthCheck();
      setServiceHealth(health);
      setHealthMessage(health.message || 'Service status updated.');
    } catch (error) {
      setServiceHealth({
        status: 'DOWN',
        checks: {},
        message: 'Backend is unreachable. Check API deployment and network access.'
      });
      setHealthMessage('Backend is unreachable. Check API deployment and network access.');
    }
  };

  const generateSessionId = () => {
    return 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSendMessage = async (messageText, imageData = null) => {
    if (!messageText && !imageData) return;

    const userMessage = {
      id: Date.now(),
      message: messageText,
      isUser: true,
      timestamp: new Date().toISOString(),
      imageUrl: imageData
    };

    setMessages(prev => [...prev, userMessage]);
    setIsLoading(true);

    try {
      if (serviceHealth?.status === 'DOWN') {
        toast.error(serviceHealth?.message || 'Backend is unavailable right now.');
      } else if (serviceHealth?.status === 'DEGRADED') {
        toast(serviceHealth?.message || 'AI provider is degraded. Attempting fallback response.');
      }

      if (imageData) {
        const response = await chatAPI.sendImageMessage(messageText, imageData, sessionId);
        const aiMessage = {
          id: Date.now() + 1,
          message: response.response,
          isUser: false,
          timestamp: response.timestamp
        };
        setMessages(prev => [...prev, aiMessage]);
        updateChatHistory(sessionId, messageText, response.response);
        await refreshConversations();
        if (speechService.isSupported()) {
          setTimeout(() => speechService.speak(response.response), 500);
        }
      } else {
        // Streaming for text messages
        const aiMessageId = Date.now() + 1;
        const initialAiMessage = {
          id: aiMessageId,
          message: '',
          isUser: false,
          timestamp: new Date().toISOString()
        };

        setMessages(prev => [...prev, initialAiMessage]);

        let fullResponse = '';
        try {
          await chatAPI.streamMessage(messageText, sessionId, (chunk) => {
            fullResponse += chunk;
            setMessages(prev => prev.map(msg => 
              msg.id === aiMessageId ? { ...msg, message: fullResponse } : msg
            ));
          });
        } catch (streamError) {
          console.error('Streaming failed, falling back to standard response:', streamError);
          const response = await chatAPI.sendMessage(messageText, sessionId);
          fullResponse = response.response || response.error || 'The assistant could not generate a response.';
          setMessages(prev => prev.map(msg =>
            msg.id === aiMessageId ? { ...msg, message: fullResponse } : msg
          ));
          if (streamError?.message) {
            toast.error(`Streaming failed: ${streamError.message}`);
          }
        }

        updateChatHistory(sessionId, messageText, fullResponse);
        await refreshConversations();

        if (speechService.isSupported()) {
          setTimeout(() => speechService.speak(fullResponse), 500);
        }
      }

    } catch (error) {
      console.error('Error sending message:', error);
      toast.error(error.message || 'Failed to send message. Please try again.');

      const errorMessage = {
        id: Date.now() + 2,
        message: error.message || 'The assistant is unavailable right now. Check AI provider configuration and try again.',
        isUser: false,
        timestamp: new Date().toISOString()
      };
      
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const updateChatHistory = (chatId, userMsg, aiMsg) => {
    setChatHistory(prev => {
      const existingChat = prev.find(chat => chat.id === chatId);
      if (existingChat) {
        return prev.map(chat => 
          chat.id === chatId 
            ? { ...chat, lastMessage: userMsg, updatedAt: new Date() }
            : chat
        );
      } else {
        return [...prev, {
          id: chatId,
          title: userMsg.length > 30 ? userMsg.substring(0, 30) + '...' : userMsg,
          lastMessage: userMsg,
          createdAt: new Date(),
          updatedAt: new Date()
        }];
      }
    });
  };

  const handleNewChat = () => {
    const newSessionId = generateSessionId();
    setSessionId(newSessionId);
    setCurrentChatId(newSessionId);
    setMessages([{
      id: 1,
      message: "New conversation started! How can I help you today?",
      isUser: false,
      timestamp: new Date().toISOString()
    }]);
  };

  const handleSelectChat = (chatId) => {
    loadConversation(chatId);
  };

  return (
    <div className="flex h-screen bg-gradient-to-br from-beige-50 via-white to-sand-50">
      {/* Sidebar */}
      <Sidebar
        onNewChat={handleNewChat}
        chatHistory={chatHistory}
        currentChatId={currentChatId}
        onSelectChat={handleSelectChat}
      />

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col">
        {/* Chat Header */}
        <motion.header
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-navy-800/80 backdrop-blur-sm border-b border-navy-700 px-6 py-4"
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 bg-gradient-to-br from-sand-500 to-sand-700 rounded-xl flex items-center justify-center shadow-lg">
                <Bot className="w-6 h-6 text-white" />
              </div>
              <div>
                <h1 className="text-lg font-semibold text-warm-900">AI.BH Assistant</h1>
                <p className="text-sm text-warm-600">
                  {isLoading ? 'Thinking...' : serviceHealth?.status === 'UP' ? 'Ready to help' : 'Service needs attention'}
                </p>
              </div>
            </div>

            <div className="flex items-center space-x-2">
              <div className="flex items-center space-x-1 text-xs text-warm-500">
                {serviceHealth?.status === 'UP' ? (
                  <>
                    <CheckCircle2 className="w-4 h-4 text-green-500" />
                    <span>Online</span>
                  </>
                ) : (
                  <>
                    <AlertTriangle className="w-4 h-4 text-amber-500" />
                    <span>Degraded</span>
                  </>
                )}
              </div>
            </div>
          </div>
        </motion.header>

        {serviceHealth?.status !== 'UP' && (
          <div className="border-b border-amber-200 bg-amber-50 px-6 py-3 text-sm text-amber-800">
            {healthMessage}
          </div>
        )}

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto chat-container">
          <div className="max-w-4xl mx-auto px-6 py-8">
            {messages.length === 0 ? (
              // Empty State
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="text-center py-16"
              >
                <div className="w-20 h-20 bg-gradient-to-br from-sand-500 to-sand-700 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-2xl">
                  <Bot className="w-10 h-10 text-white" />
                </div>
                <h2 className="text-2xl font-bold text-warm-900 mb-4">
                  Welcome to AI.BH
                </h2>
                <p className="text-warm-600 mb-8 max-w-md mx-auto">
                  Your intelligent assistant is ready to help you learn, create, and solve problems. Start a conversation below!
                </p>
                <div className="flex flex-wrap justify-center gap-3">
                  {[
                    "Explain a complex topic",
                    "Help with coding",
                    "Analyze an image",
                    "Creative writing"
                  ].map((suggestion, index) => (
                    <motion.button
                      key={index}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => handleSendMessage(suggestion)}
                      className="px-4 py-2 bg-navy-800 hover:bg-navy-900 text-warm-700 rounded-xl transition-colors border border-beige-300"
                    >
                      {suggestion}
                    </motion.button>
                  ))}
                </div>
              </motion.div>
            ) : (
              // Messages
              <>
                {messages.map((msg, index) => (
                  <ChatMessage
                    key={msg.id}
                    message={msg.message}
                    isUser={msg.isUser}
                    timestamp={msg.timestamp}
                    imageUrl={msg.imageUrl}
                    index={index}
                  />
                ))}

                <AnimatePresence>
                  {isLoadingHistory && <TypingIndicator />}
                </AnimatePresence>

                <AnimatePresence>
                  {isLoading && <TypingIndicator />}
                </AnimatePresence>
                
                <div ref={messagesEndRef} />
              </>
            )}
          </div>
        </div>

        {/* Input Area */}
        <ChatInput 
          onSendMessage={handleSendMessage}
          disabled={isLoading || serviceHealth?.status !== 'UP'}
          statusMessage={serviceHealth?.status === 'UP'
            ? 'Ask anything. If project-specific knowledge is missing, upload text documents to improve answers.'
            : healthMessage}
        />
      </div>
    </div>
  );
};

export default ChatPage;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { Bot, Mail, Lock, Eye, EyeOff } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';

const LoginPage = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  
  const { login } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  
  const from = location.state?.from?.pathname || '/chat';

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Client-side validation
    if (!formData.email || !formData.password) {
      toast.error('Please fill in all fields');
      return;
    }
    
    if (!formData.email.includes('@')) {
      toast.error('Please enter a valid email address');
      return;
    }
    
    setLoading(true);

    try {
      const result = await login(formData.email, formData.password);
      
      if (result.success) {
        toast.success('Welcome back!');
        navigate(from, { replace: true });
      } else {
        toast.error(result.error);
      }
    } catch (error) {
      toast.error('Something went wrong. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-beige-50 via-white to-sand-50 flex items-center justify-center p-4">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className="w-full max-w-md"
      >
        {/* Header */}
        <div className="text-center mb-8">
          <motion.div
            initial={{ scale: 0.8 }}
            animate={{ scale: 1 }}
            transition={{ duration: 0.5, delay: 0.1 }}
            className="inline-flex items-center justify-center w-16 h-16 bg-gradient-to-br from-sand-500 to-sand-700 rounded-2xl mb-4 shadow-lg"
          >
            <Bot className="w-8 h-8 text-white" />
          </motion.div>
          <h1 className="text-3xl font-bold text-warm-900 mb-2">Welcome Back</h1>
          <p className="text-warm-600">Sign in to continue your AI journey</p>
        </div>

        {/* Login Form */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.2 }}
          className="bg-navy-800 rounded-2xl shadow-xl p-8 border border-navy-700"
        >
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Email Field */}
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-warm-800 mb-2">
                Email Address
              </label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-warm-400" />
                <input
                  type="email"
                  id="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  className="input-field pl-11"
                  placeholder="Enter your email"
                  required
                />
              </div>
            </div>

            {/* Password Field */}
            <div>
              <label htmlFor="password" className="block text-sm font-medium text-warm-800 mb-2">
                Password
              </label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-warm-400" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  id="password"
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  className="input-field pl-11 pr-11"
                  placeholder="Enter your password"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-warm-400 hover:text-warm-600 transition-colors"
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
            </div>

            {/* Submit Button */}
            <button
              type="submit"
              disabled={loading}
              className="w-full btn-primary flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? (
                <motion.div
                  animate={{ rotate: 360 }}
                  transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
                  className="w-5 h-5 border-2 border-white border-t-transparent rounded-full"
                />
              ) : (
                'Sign In'
              )}
            </button>
          </form>

          {/* Demo Credentials */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.5 }}
            className="mt-6 p-4 bg-navy-700 rounded-xl border border-navy-700"
          >
            <p className="text-sm text-warm-600 mb-2 font-medium">Demo Credentials:</p>
            <p className="text-xs text-warm-500">Email: demo@aibh.com</p>
            <p className="text-xs text-warm-500">Password: demo1234</p>
            <p className="text-xs text-warm-400 mt-2 italic">Note: Sign up first if demo user doesn't exist</p>
          </motion.div>

          {/* Sign Up Link */}
          <div className="mt-6 text-center">
            <p className="text-warm-600">
              Don't have an account?{' '}
              <Link to="/signup" className="text-sand-600 hover:text-sand-700 font-medium transition-colors">
                Sign up here
              </Link>
            </p>
          </div>
        </motion.div>

        {/* Back to Home */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.6 }}
          className="text-center mt-6"
        >
          <Link to="/" className="text-warm-500 hover:text-warm-700 transition-colors">
            ← Back to Home
          </Link>
        </motion.div>
      </motion.div>
    </div>
  );
};

export default LoginPage;

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { BrowserRouter } from 'react-router-dom';
import LoginPage from './LoginPage';

// Mock react-hot-toast
jest.mock('react-hot-toast', () => ({
  error: jest.fn(),
  success: jest.fn(),
}));

// Mock AuthContext
const mockLogin = jest.fn();
jest.mock('../contexts/AuthContext', () => ({
  useAuth: () => ({
    login: mockLogin,
  }),
}));

import { toast } from 'react-hot-toast';

describe('LoginPage', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  const renderComponent = () => {
    return render(
      <BrowserRouter>
        <LoginPage />
